/* !
 * \file mergemode.asc
 * \brief 演示使用asc_copy进行矢量数据寄存器间的数据搬运，mask为1的位置填充src元素，为0的位置保持dst元素（MODE_MERGING）
 */

#include <cstdint>
#include <vector>
#include <algorithm>
#include <iostream>

#include "acl/acl.h"
