        asc_loadalign(src1_reg, y_local + i * one_rep_size);
        asc_loadalign_postupdate(vmask, mask_local, mask_rep_size);
        asc_select(dst_reg, src0_reg, src1_reg, vmask);
        asc_storealign(z_local + i * one_rep_size, dst_reg, store_mask);
    }
}

__vector__ __global__ void select_custom(__gm__ float* x, __gm__ float* y, __gm__ uint8_t* mask, __gm__ float* z)
{
    asc_init();

    constexpr uint32_t block_length = TOTAL_LENGTH / NUM_BLOCKS;

    __gm__ float* x_gm = x + block_idx * block_length;
    __gm__ float* y_gm = y + block_idx * block_length;
    __gm__ uint8_t* mask_gm = mask + block_idx * block_length / 2;
    __gm__ float* z_gm = z + block_idx * block_length;

    __ubuf__ float x_local[block_length];
    __ubuf__ float y_local[block_length];
    __ubuf__ uint8_t mask_local[block_length / 2];
    __ubuf__ float z_local[block_length];

    uint32_t burst_length = block_length * 4;
    uint32_t mask_burst_length = (block_length / 2) * 1;
    uint64_t src_stride = 0;
    uint32_t dst_stride = 0;

    asc_copy_gm2ub_align((__ubuf__ float*)x_local, x_gm, burst_length);
    asc_copy_gm2ub_align((__ubuf__ float*)y_local, y_gm, burst_length);
    asc_copy_gm2ub_align((__ubuf__ uint8_t*)mask_local, mask_gm, mask_burst_length);
    asc_sync_notify(PIPE_MTE2, PIPE_V, EVENT_ID0);
    asc_sync_wait(PIPE_MTE2, PIPE_V, EVENT_ID0);

    uint16_t one_rep_size = asc_get_vf_len() / sizeof(float);
    uint16_t mask_rep_size = asc_get_vf_len() / 8;
    uint16_t repeat_time = AscendC::Std::ceil_div(block_length, one_rep_size);
    select_vf(
        (__ubuf__ float*)x_local, (__ubuf__ float*)y_local, (__ubuf__ uint32_t*)mask_local, (__ubuf__ float*)z_local,
        block_length, one_rep_size, mask_rep_size, repeat_time);
    asc_sync_notify(PIPE_V, PIPE_MTE3, EVENT_ID0);
    asc_sync_wait(PIPE_V, PIPE_MTE3, EVENT_ID0);

    asc_copy_ub2gm_align(
        z_gm, (__ubuf__ float*)z_local, BLK_NUM, burst_length, asc_store_l2_cache_mode::NORMAL_FIRST_VICTIM, src_stride,
        dst_stride);
    //! [asc_sync__z]
    asc_sync();
    //! [asc_sync__z]
}

std::vector<float> kernel_select(std::vector<float>& x, std::vector<float>& y, std::vector<uint8_t>& mask)
{
    constexpr uint32_t num_blocks = NUM_BLOCKS;
    uint32_t total_length = x.size();
    size_t x_byte_size = total_length * sizeof(float);
    size_t mask_byte_size = total_length * sizeof(float) / 8;
    int32_t device_id = 0;
    uint8_t* x_host = reinterpret_cast<uint8_t*>(x.data());
    uint8_t* y_host = reinterpret_cast<uint8_t*>(y.data());
    uint8_t* mask_host = mask.data();
    uint8_t* z_host = nullptr;
    float* x_device = nullptr;
    float* y_device = nullptr;
    uint8_t* mask_device = nullptr;
    float* z_device = nullptr;

    aclInit(nullptr);
    aclrtSetDevice(device_id);

    aclrtMallocHost((void**)(&z_host), x_byte_size);
    aclrtMalloc((void**)&x_device, x_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMalloc((void**)&y_device, x_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMalloc((void**)&mask_device, mask_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMalloc((void**)&z_device, x_byte_size, ACL_MEM_MALLOC_HUGE_FIRST);

    aclrtMemcpy((uint8_t*)x_device, x_byte_size, x_host, x_byte_size, ACL_MEMCPY_HOST_TO_DEVICE);
    aclrtMemcpy((uint8_t*)y_device, x_byte_size, y_host, x_byte_size, ACL_MEMCPY_HOST_TO_DEVICE);
    aclrtMemcpy(mask_device, mask_byte_size, mask_host, mask_byte_size, ACL_MEMCPY_HOST_TO_DEVICE);

    select_custom<<<num_blocks, 0>>>(x_device, y_device, mask_device, z_device);
    aclrtSynchronizeDevice();

    aclrtMemcpy(z_host, x_byte_size, (uint8_t*)z_device, x_byte_size, ACL_MEMCPY_DEVICE_TO_HOST);
    std::vector<float> z((float*)z_host, (float*)(z_host + x_byte_size));

    aclrtFree(x_device);
    aclrtFree(y_device);
    aclrtFree(mask_device);
    aclrtFree(z_device);
    aclrtFreeHost(z_host);

    aclrtResetDevice(device_id);
    aclFinalize();

    return z;
}

uint32_t verify_result(std::vector<float>& output, std::vector<float>& golden)
{
    if (std::equal(golden.begin(), golden.end(), output.begin())) {
        std::cout << "test pass!" << std::endl;
        return 0;
